//
// D2 DERIVED COPY of experiments/P1-pocket-top/rtl/p1_sram_port.sv (generated by make_d2_derived.py): module renamed to
// d2_sram_port, the simulation-only rd_edges $display removed. The port logic is unchanged; the D2 top ties rd_edges
// to a constant parameter. sample_now / n_reads / n_writes / overlap are observation outputs (unconnected in
// synthesis, pruned).
//
// p1_sram_port: CPU work RAM on the Pocket's asynchronous 128K x 16 SRAM (A[16:0], DQ[15:0], OE/WE/UB/LB, no CE), clk_sys.
// P1 Pocket-top simulation (stage S2), exploratory. Every pin is a plain register (IOE-packable, as the plan's
// "plain registered pins"); read data is captured in an input register.
//
// Read  (wram_ext_rd level from the derived s32_core): edge E1 = first edge that sees the request: A, OE=0, UB=LB=0 are
//       registered. The DQ input is sampled into q on edge E1 + RD_EDGES (RD_EDGES clk_sys after the address edge, i.e.
//       RD_EDGES x 20.696 ns) and rdy is raised on that same edge; the core acknowledges on the next edge. rdy and OE fall
//       when the request drops.
// Write (wram_ext_we level; the core acknowledges it on its first cycle, so the request is captured into a holding
//       register on its rising edge): E1 A/DQ/UB/LB registered, DQ driven, OE=1; E2 WE=0; E4 WE=1 (WE low 2 clk_sys =
//       41.4 ns); E5 DQ released, port free. Address and data are stable one clock before WE falls and after it rises.
// A request that arrives while the port is busy waits (read) or is held (write); `overlap` counts those cases (expected 0:
// the V60 bus adapter leaves >= 3 clk_sys between 16-bit cycles).
module d2_sram_port (
    input              clk,
    input        [2:0] rd_edges,    // RD_EDGES below, 1..7 (quasi-static)
    input              rst,
    input       [15:0] addr,
    input       [15:0] wdata,
    input        [1:0] be,
    input              we,
    input              rd,
    output reg  [15:0] q = 16'h0,
    output reg         rdy = 1'b0,
    // pins
    output reg  [16:0] sram_a = 17'h0,
    output reg  [15:0] sram_dq_o = 16'h0,
    output reg         sram_dq_oe = 1'b0,
    input       [15:0] sram_dq_i,
    output reg         sram_oe_n = 1'b1,
    output reg         sram_we_n = 1'b1,
    output reg         sram_ub_n = 1'b1,
    output reg         sram_lb_n = 1'b1,
    // simulation observation
    output reg         sample_now = 1'b0,   // high during the edge on which q samples the pins (for the testbench check)
    output reg  [31:0] n_reads = 0,
    output reg  [31:0] n_writes = 0,
    output reg  [31:0] overlap = 0
);

typedef enum logic [2:0] { S_IDLE, S_RD, S_RDH, S_W1, S_W2, S_W3, S_W4 } st_t;
st_t st = S_IDLE;
reg [2:0]  cnt = 0;
reg        we_d = 1'b0;
reg        wpend = 1'b0;
reg [15:0] wa = 0, wd = 0;
reg  [1:0] wb = 0;

always @(posedge clk) begin
    we_d <= we;
    if (rst) begin
        st <= S_IDLE; rdy <= 1'b0; wpend <= 1'b0; sram_oe_n <= 1'b1; sram_we_n <= 1'b1; sram_dq_oe <= 1'b0;
        sram_ub_n <= 1'b1; sram_lb_n <= 1'b1; sample_now <= 1'b0;
    end else begin
        // capture every write request on its rising edge (the core does not wait for it)
        if (we && !we_d) begin
            if (wpend || st == S_W1 || st == S_W2 || st == S_W3 || st == S_W4 || st == S_RD) overlap <= overlap + 1;
            wpend <= 1'b1; wa <= addr; wd <= wdata; wb <= be;
        end
        // next-state: sample_now is a one-edge flag that precedes the sampling edge
        case (st)
        S_IDLE: begin
            if (wpend || (we && !we_d)) begin
                sram_a     <= {1'b0, (wpend ? wa : addr)};
                sram_dq_o  <= wpend ? wd : wdata;
                sram_ub_n  <= ~(wpend ? wb[1] : be[1]);
                sram_lb_n  <= ~(wpend ? wb[0] : be[0]);
                sram_dq_oe <= 1'b1;
                sram_oe_n  <= 1'b1;
                wpend      <= 1'b0;
                n_writes   <= n_writes + 1;
                st <= S_W1;
            end
            else if (rd && !rdy) begin
                sram_a    <= {1'b0, addr};
                sram_oe_n <= 1'b0;
                sram_ub_n <= 1'b0;
                sram_lb_n <= 1'b0;
                cnt       <= rd_edges - 3'd1;
                sample_now <= (rd_edges == 3'd1);
                n_reads   <= n_reads + 1;
                st <= S_RD;
            end
        end
        S_RD: begin
            if (cnt == 0) begin
                q <= sram_dq_i; rdy <= 1'b1; sample_now <= 1'b0; st <= S_RDH;
            end else begin
                cnt <= cnt - 1'd1;
                sample_now <= (cnt == 3'd1);
            end
        end
        S_RDH: if (!rd) begin rdy <= 1'b0; sram_oe_n <= 1'b1; sram_ub_n <= 1'b1; sram_lb_n <= 1'b1; st <= S_IDLE; end
        S_W1: begin sram_we_n <= 1'b0; st <= S_W2; end
        S_W2: st <= S_W3;
        S_W3: begin sram_we_n <= 1'b1; st <= S_W4; end
        S_W4: begin sram_dq_oe <= 1'b0; sram_ub_n <= 1'b1; sram_lb_n <= 1'b1; st <= S_IDLE; end
        default: st <= S_IDLE;
        endcase
    end
end

endmodule
